CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reports (week TEXT PRIMARY KEY, captured_at TEXT NOT NULL, scheduled_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS balances (week TEXT NOT NULL REFERENCES reports(week), kind TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL, balance TEXT NOT NULL, rank INTEGER NOT NULL, PRIMARY KEY(week, kind, id));
CREATE TABLE IF NOT EXISTS deliveries (week TEXT NOT NULL REFERENCES reports(week), part INTEGER NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('PENDING','SENDING','SENT','FAILED','UNCERTAIN')), PRIMARY KEY(week,part));
